import { BrandCard } from "@/components/ui/cards/BrandCard";
import React from "react";
import brands from "@/data/brandLogos"

// Mock Data
const BRANDS = [
  { name: "Nike", slug: "nike", logo: "/images/brand-logos/nike.png" },
  { name: "Adidas", slug: "adidas", logo: "/images/brand-logos/adidas.png" },
  { name: "Jordan", slug: "jordan", logo: "/images/brand-logos/jordan.png" },
  { name: "Puma", slug: "puma", logo: "/images/brand-logos/puma.png" },
  { name: "New Balance", slug: "new-balance", logo: "/images/brand-logos/newbalance.png" },
  { name: "Reebok", slug: "reebok", logo: "/images/brand-logos/reebok.png" },
];


export default function BrandsPage() {
  return (
    <main className="min-h-screen bg-black text-white p-6 md:pt-24">
      <header className="mb-12">
        <h1 className="text-4xl font-black uppercase italic tracking-tighter">
          All Brands
        </h1>
        <p className="text-white/40 text-sm mt-2">
          Explore our premium collection by manufacturer
        </p>
      </header>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {BRANDS.map((brand) => (
          <BrandCard key={brand.slug} brand={brand} />
        ))}
      </div>
    </main>
  );
}
